function init(){defaults({profiles:{工作日:null,周末:null},profile:'周末',sessions:[],timerV3:null});if(p.conditionDate&&p.conditionDate!==today())state.agreement.conditionMet=false;p.conditionDate=today();if(!p.profiles[p.profile])p.profiles[p.profile]=clone(state.agreement)}init();
const allowance=()=>{const a=state.agreement;return a.base+(a.conditionMet?a.bonus:0)},used=()=>p.sessions.filter(x=>x.date===today()).reduce((a,x)=>a+x.minutes,0);
function timerElapsed(){if(!p.timerV3)return 0;return p.timerV3.elapsed+(p.timerV3.started?Date.now()-p.timerV3.started:0)}
function tick(){const el=$('#timer-clock');if(!el)return;const seconds=Math.max(0,Math.ceil(((p.timerV3?.limit||0)*60000-timerElapsed())/1000));el.textContent=`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;const hint=$('#timer-hint');if(hint&&p.timerV3)hint.textContent=seconds===0?'约定时间到了，结束并一起回顾吧。':p.timerV3.started?'正在计时，记得按约定休息。':'已暂停，准备好再继续。'}
function render(){nav();const a=state.agreement,remaining=Math.max(0,allowance()-used());
if(active===0){$('#app').innerHTML=`<div class="screen-body"><section class="card" style="text-align:center"><span class="eyebrow">${p.profile} · 我们共同的约定</span><div class="circle-meter" style="--pct:${Math.min(100,used()/Math.max(1,allowance())*100)}"><div><small>${p.timerV3?'本次剩余':'今天还可以使用'}</small><b id="timer-clock">${remaining}</b>${!p.timerV3?'<small>分钟</small>':''}</div></div><p id="timer-hint" class="hint">${p.timerV3?'':`今天已记录 ${used()} / ${allowance()} 分钟`}</p><div class="row" style="justify-content:center;margin-top:22px">${p.timerV3?btn(p.timerV3.started?'暂停计时':'继续计时','pause','secondary')+btn('结束并记录','end'):btn('开始本次使用','start','primary full',!remaining)}</div></section><section class="card"><div class="between"><div><h3>我们的约定</h3><p class="hint">基础 ${a.base} 分钟 · 额外 ${a.bonus} 分钟</p></div>${btn('查看','view','secondary')}</div><label class="checkbox" style="margin-top:18px"><input id="condition" type="checkbox" ${a.conditionMet?'checked':''} ${p.timerV3?'disabled':''}>${esc(a.condition)}，双方已确认</label></section><p class="subtle" style="margin-top:18px">这个工具帮助你们协商和记录，不能锁住手机或读取其他应用。离开页面后会按真实经过时间计算，请主动结束计时；不足 1 分钟按 1 分钟记录。</p></div>`;on('view',()=>go(1));on('start',()=>{p.timerV3={started:Date.now(),elapsed:0,limit:remaining,date:today()};commit('计时开始')});on('pause',()=>{if(p.timerV3.started){p.timerV3.elapsed=timerElapsed();p.timerV3.started=null}else p.timerV3.started=Date.now();commit()});on('end',()=>{const elapsed=timerElapsed();const minutes=Math.max(1,Math.ceil(elapsed/60000));p.sessions.push({id:uid(),date:p.timerV3.date,minutes});p.timerV3=null;commit(`本次记录 ${minutes} 分钟`)});$('#condition').onchange=e=>{a.conditionMet=e.target.checked;p.profiles[p.profile]=clone(a);commit()};if(p.timerV3)tick();}
if(active===1){$('#app').innerHTML=`<div class="two-col"><div>${hero('先听见彼此',`${a.base}<small>分钟共同约定</small>`,'孩子和家人都有表达期待的空间。','phone')}<div class="segmented" style="margin-top:20px">${['工作日','周末'].map(d=>`<button data-profile="${d}" class="${d===p.profile?'selected':''}" ${p.timerV3?'disabled':''}>${d}</button>`).join('')}</div><section class="card"><form id="agreement" class="stack"><div class="fields">${field('孩子希望 / 分钟','child','number',a.child,'required min="0" max="240"')}${field('家人建议 / 分钟','parent','number',a.parent,'required min="0" max="240"')}</div>${field('一起决定 / 分钟','base','number',a.base,'required min="0" max="240"')}<details><summary>额外时间怎么约定</summary><div class="stack">${field('额外时间 / 分钟','bonus','number',a.bonus,'required min="0" max="120"')}${field('双方认可的条件','condition','text',a.condition,'required maxlength="100"')}</div></details><button class="primary" ${p.timerV3?'disabled':''}>双方同意，保存约定</button>${p.timerV3?'<p class="hint">先结束正在进行的计时，再修改约定。</p>':''}</form></section></div><aside class="card"><h3>聊一聊，再做决定</h3><ol style="padding-left:20px;line-height:2.3;font-size:14px"><li>我想用屏幕做什么？</li><li>为什么需要这些时间？</li><li>什么时候应该暂停？</li></ol><p class="hint">工具不会自动把双方的数字取平均，也不会替任何一方做决定。</p></aside></div>`;actions('profile',d=>{p.profiles[p.profile]=clone(a);p.profile=d;state.agreement=clone(p.profiles[d]||{child:30,parent:20,base:25,bonus:0,condition:'完成双方约定的小任务',conditionMet:false});commit()});form('agreement',v=>{state.agreement={child:+v.child,parent:+v.parent,base:+v.base,bonus:+v.bonus,condition:v.condition,conditionMet:false};p.profiles[p.profile]=clone(state.agreement);commit('这份共同约定已保存');go(0)})}
if(active===2){$('#app').innerHTML=`<div class="screen-body">${heading('使用后的回顾',btn('补记一次','manual',''))}<section class="card"><h3>实际使用记录</h3>${list([...p.sessions].reverse(),x=>`<div class="list-item"><span class="tile-icon">${icon('clock')}</span><div class="content"><strong>${x.minutes} 分钟</strong><p>${x.date}</p></div></div>`)}</section><section class="card"><form id="review" class="stack">${textfield('下次我们想怎样调整？','note','',300)}<button class="primary">记下这次讨论</button></form>${list([...state.reviews].reverse(),r=>`<div class="list-item"><div class="content"><strong>${esc(r.note||r.reflection||'已记录一次回顾')}</strong><p>${esc(r.date)}</p></div></div>`)}</section></div>`;on('manual',()=>editModal('补记使用时间',field('日期','date','date',today(),`required max="${today()}"`)+field('实际用了多少分钟','minutes','number',15,'required min="1" max="1440"'),v=>{p.sessions.push({id:uid(),date:v.date,minutes:+v.minutes});commit()}));form('review',v=>{state.reviews.push({date:today(),note:v.note});commit('讨论已记下')})}}
shell([['计时','clock'],['约定','people'],['回顾','list']]);render();setInterval(tick,1000);
